#include <iostream>
#include <map>

using namespace std;

int ma(const map<int, int>& f, int n, int m) {
    if (n <= 0) return 0;

    int lo = 1, h = m / n;

    while (lo <= h) {
        int mid = lo + (h - lo) / 2;
        int k = 0;

        for (const auto& entry : f) {
            k += entry.second / mid;
        }

        if (k >= n)
            lo = mid + 1;
        else
            h = mid - 1;
    }

    return h;
}

int main() {
    int n, m;
    cin >> n >> m;

    map<int, int> f;
    for (int i = 0, x; i < m; ++i) {
        cin >> x;
        ++f[x];
    }

    cout << ma(f, n, m);
    return 0;
}

